export function run_ops(ops: string[]): number {
  let balance = 0;
  for (let i = 0; i < ops.length; i++) {
    const pos = i + 1;
    const m = /^(deposit|withdraw) (\d+)$/.exec(ops[i]);
    if (m === null) {
      throw new Error(`bad op at op ${pos}`);
    }
    const amount = Number(m[2]);
    if (m[1] === "deposit") {
      balance += amount;
    } else {
      if (balance - amount < 0) {
        throw new Error(`insufficient funds at op ${pos}`);
      }
      balance -= amount;
    }
  }
  return balance;
}
